// === Tab: mySketch ===
OPC.slider('curliness', 1.3,5, 20);
OPC.slider('velocity', 2, 0.5, 30);

let img1;
let img2;
let img3;
let particles = [];
let edgeColour;

function preload(){
	img1 = loadImage("https://openprocessing.org/sketch/1890951/files/793A8AD6-624B-4014-8750-54F504770DCD.jpeg");
	img2 = loadImage("https://openprocessing.org/sketch/1890951/files/IMG_1241.JPG");
	img3 = loadImage("https://openprocessing.org/sketch/1890951/files/C555C0F9-199F-4ACB-B461-A83A5EE2A212.jpeg");

	//img.resize(1000,0)
}

function setup() {

	createCanvas(630, 500);
	img1.resize(width, 0);
	img2.resize(width,0);
  img3.resize(width,0);

	background(255);


	colorMode(HSB, 155);

	edgeColour = color(random(225), 250, 220, 10);

	for(let i = 0; i < 1000; i++){
		particles[i] = new Particle(edgeColour, curliness);
	}
}

function draw() {
	for(let i = 0; i < particles.length; i++){


    if(particles[i].pos.y < 0 || particles[i].pos.y > height 
			                        || particles[i].pos.x < 0 
			                        || particles[i].pos.x > width)
		{

      particles[i] = new Particle(edgeColour);
    }

    particles[i].update(velocity);
    particles[i].show();
  }
}






// === Tab: tab2 ===
class Particle{

	constructor(){

		colorMode(RGB, 100,135,123);

    colorMode(RGB, 129,135,123);
		this.rand = random(3);


		this.pos = createVector(0, random(height));
		//this.pos = createVector(random(width), random(height));
		this.vel = createVector(1, 0);
		//this.vel.rotate(random(TWO_PI));

		this.c = color(102);
	}

	update(velocity){

		this.past = createVector(this.pos.x, this.pos.y);

		this.pos.add(p5.Vector.mult(this.vel, velocity));
		this.c = 125;

		let ratio= brightness(img1.get(int(this.pos.x), int(this.pos.y))) / 255;
		let ratio_1 = brightness(img2.get(int(this.pos.x), int(this.pos.y))) / 255;
		let ratio_2= brightness(img3.get(int(this.pos.x), int(this.pos.y))) / 255;



		if (second()<60) {if(second()>40){ratio_2=ratio;}}
		if (second()<40) {if(second()>=20){ratio = ratio_2;}}
		if (second()<20) {if(second()>=0){ratio = ratio_1;}}
		this.vel.rotate(random(-HALF_PI * pow(ratio, 3-curliness), HALF_PI * pow(ratio, 3-curliness)));
		this.vel.rotate(random(-HALF_PI * pow(ratio_1, 3-curliness), HALF_PI * pow(ratio_1, 3-curliness)));
		this.vel.rotate(random(-HALF_PI * pow(ratio_2, 3-curliness), HALF_PI * pow(ratio_2, 3-curliness)));



		this.c = color(map(ratio,0, 1, 0, red(edgeColour)),  
											 map(ratio, 0, 1, 0, green(edgeColour)),
											 map(ratio, 0, 1, 0, blue(edgeColour)),
										   200 - ratio * 255);

	}

	show(){


		stroke(this.c);

		line(this.pos.x, this.pos.y, this.past.x, this.past.y);
	}

}

